    21	public class Main {
    22	    /** Taxa de turismo da prefeitura, por hóspede por noite. Muda todo ano. */
    23	    static final BigDecimal TOURISM_TAX_PER_GUEST_NIGHT = new BigDecimal("4.50");
    24	
    25	    public static void main(String[] args) {
    26	        Database database = Database.connect(System.getenv("DB_URL"), System.getenv("DB_USER"),
    27	                System.getenv("DB_PASSWORD"));
    28	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
    29	        build(new PostgresReservationRepository(database), new PostgresMessageRepository(database)).start(port);
    30	    }
    31	
    32	    public static Javalin build(ReservationRepository reservations, MessageRepository messages) {
    33	        RoomCatalog rooms = new RoomCatalog();
    34	        ReservationService service = new ReservationService(rooms, reservations, messages);
    35	        List<Report<?>> available = List.of(
    36	                new OccupancyReport(reservations, rooms),
    37	                new RevenueReport(reservations),
    38	                new TourismTaxReport(reservations, TOURISM_TAX_PER_GUEST_NIGHT),
    39	                new RatePlanReport(reservations));
    40	        return new Api(rooms, service, messages, new ReportRegistry(available)).create();
    41	    }
