     1	package com.pousada.web;
     2	
     3	import com.fasterxml.jackson.databind.ObjectMapper;
     4	import com.fasterxml.jackson.databind.SerializationFeature;
     5	import com.fasterxml.jackson.databind.json.JsonMapper;
     6	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
     7	import com.pousada.domain.DomainException;
     8	import com.pousada.domain.ErrorCode;
     9	import com.pousada.domain.RoomCatalog;
    10	import com.pousada.report.Report;
    11	import com.pousada.report.ReportRegistry;
    12	import com.pousada.repository.MessageRepository;
    13	import com.pousada.service.ReservationService;
    14	import io.javalin.Javalin;
    15	import io.javalin.http.Context;
    16	import io.javalin.json.JavalinJackson;
    17	import java.util.Map;
    18	
    19	public class Api {
    20	    private final RoomCatalog rooms;
    21	    private final ReservationService service;
    22	    private final MessageRepository messages;
    23	    private final ReportRegistry reports;
    24	    private final ObjectMapper mapper = JsonMapper.builder()
    25	            .addModule(new JavaTimeModule())
    26	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
    27	            .enable(SerializationFeature.WRITE_BIGDECIMAL_AS_PLAIN)
    28	            .build();
    29	
    30	    public Api(RoomCatalog rooms, ReservationService service, MessageRepository messages, ReportRegistry reports) {
    31	        this.rooms = rooms;
    32	        this.service = service;
    33	        this.messages = messages;
    34	        this.reports = reports;
    35	    }
    36	
    37	    public Javalin create() {
    38	        Javalin app = Javalin.create(config -> config.jsonMapper(new JavalinJackson(mapper, false)));
    39	
    40	        app.get("/rooms", ctx -> ctx.json(rooms.all()));
    41	        app.post("/reservations", ctx -> ctx.status(201).json(service.create(RequestParser.parse(mapper, ctx.body()))));
    42	        app.get("/reservations/{id}", ctx -> ctx.json(service.get(id(ctx))));
    43	        app.post("/reservations/{id}/confirmation", ctx -> ctx.json(service.confirm(id(ctx))));
    44	        app.post("/reservations/{id}/cancellation", ctx -> ctx.json(service.cancel(id(ctx))));
    45	        app.post("/reservations/{id}/check-in", ctx -> ctx.json(service.checkIn(id(ctx))));
    46	        app.post("/reservations/{id}/check-out", ctx -> ctx.json(service.checkOut(id(ctx))));
    47	        app.get("/reservations/{id}/document", ctx -> ctx.json(service.document(id(ctx))));
    48	        app.get("/messages", ctx -> ctx.json(messages.findAll()));
    49	        app.get("/reports/{name}", this::report);
    50	
    51	        app.exception(DomainException.class, (e, ctx) -> error(ctx, e.code(), e.getMessage()));
    52	        app.exception(Exception.class, (e, ctx) -> {
    53	            e.printStackTrace();
    54	            ctx.status(500).json(Map.of("error", "INTERNAL_ERROR", "message", "Erro interno"));
    55	        });
    56	        app.error(404, ctx -> {
    57	            if (ctx.result() == null || ctx.result().isEmpty()) {
    58	                error(ctx, ErrorCode.NOT_FOUND, "Recurso não encontrado");
    59	            }
    60	        });
    61	        return app;
    62	    }
    63	
    64	    private void report(Context ctx) {
    65	        Report<?> report = reports.find(ctx.pathParam("name"))
    66	                .orElseThrow(() -> new DomainException(ErrorCode.NOT_FOUND, "Relatório não existe"));
    67	        ctx.contentType("text/csv; charset=utf-8").result(report.render(ctx.queryParam(report.parameter())));
    68	    }
    69	
    70	    private static long id(Context ctx) {
    71	        try {
    72	            return Long.parseLong(ctx.pathParam("id"));
    73	        } catch (NumberFormatException e) {
    74	            throw new DomainException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva não existe");
    75	        }
    76	    }
    77	
    78	    private static void error(Context ctx, ErrorCode code, String message) {
    79	        ctx.status(code.httpStatus()).json(Map.of("error", code.name(), "message", message));
    80	    }
    81	}
=== src/main/java/com/pousada/web/RequestParser.java
     1	package com.pousada.web;
     2	
     3	import com.fasterxml.jackson.databind.JsonNode;
     4	import com.fasterxml.jackson.databind.ObjectMapper;
     5	import com.pousada.domain.DomainException;
     6	import com.pousada.domain.ErrorCode;
     7	import com.pousada.domain.RatePlan;
     8	import com.pousada.service.NewReservation;
     9	import java.time.LocalDate;
    10	import java.time.format.DateTimeParseException;
    11	
    12	/** Lê o corpo do POST /reservations e recusa o que estiver faltando ou mal formado. */
    13	final class RequestParser {
    14	    private RequestParser() {
    15	    }
    16	
    17	    static NewReservation parse(ObjectMapper mapper, String body) {
    18	        JsonNode json;
    19	        try {
    20	            json = mapper.readTree(body);
    21	        } catch (Exception e) {
    22	            throw invalid("O corpo não é um JSON válido");
    23	        }
    24	        if (json == null || !json.isObject()) {
    25	            throw invalid("O corpo deve ser um objeto JSON");
    26	        }
    27	        return new NewReservation(
    28	                integer(json, "roomNumber"),
    29	                text(json, "guestName"),
    30	                text(json, "guestEmail"),
    31	                text(json, "guestCpf"),
    32	                date(json, "checkIn"),
    33	                date(json, "checkOut"),
    34	                integer(json, "guests"),
    35	                ratePlan(json));
    36	    }
    37	
    38	    private static String text(JsonNode json, String field) {
    39	        JsonNode node = json.get(field);
    40	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    41	            throw invalid("Campo '" + field + "' é obrigatório");
    42	        }
    43	        return node.asText().trim();
    44	    }
    45	
    46	    private static int integer(JsonNode json, String field) {
    47	        JsonNode node = json.get(field);
    48	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    49	            throw invalid("Campo '" + field + "' deve ser um número inteiro");
    50	        }
    51	        return node.asInt();
    52	    }
    53	
    54	    private static LocalDate date(JsonNode json, String field) {
    55	        try {
    56	            return LocalDate.parse(text(json, field));
    57	        } catch (DateTimeParseException e) {
    58	            throw invalid("Campo '" + field + "' deve estar no formato 2027-07-10");
    59	        }
    60	    }
    61	
    62	    private static RatePlan ratePlan(JsonNode json) {
    63	        try {
    64	            return RatePlan.valueOf(text(json, "ratePlan"));
    65	        } catch (IllegalArgumentException e) {
    66	            throw invalid("Campo 'ratePlan' deve ser STANDARD ou NON_REFUNDABLE");
    67	        }
    68	    }
    69	
    70	    private static DomainException invalid(String message) {
    71	        return new DomainException(ErrorCode.INVALID_REQUEST, message);
    72	    }
    73	}
