     1	package com.pousada.service;
     2	
     3	import com.pousada.domain.DomainException;
     4	import com.pousada.domain.ErrorCode;
     5	import com.pousada.domain.RatePlan;
     6	import java.time.LocalDate;
     7	
     8	public record NewReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
     9	                             LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    10	
    11	    public NewReservation {
    12	        if (!checkOut.isAfter(checkIn)) {
    13	            throw new DomainException(ErrorCode.INVALID_REQUEST, "A saída deve ser depois da entrada");
    14	        }
    15	        if (guests < 1) {
    16	            throw new DomainException(ErrorCode.INVALID_REQUEST, "É preciso ao menos um hóspede");
    17	        }
    18	    }
    19	}
=== src/main/java/com/pousada/service/ReservationService.java
     1	package com.pousada.service;
     2	
     3	import com.pousada.domain.DomainException;
     4	import com.pousada.domain.ErrorCode;
     5	import com.pousada.domain.Pricing;
     6	import com.pousada.domain.Receipt;
     7	import com.pousada.domain.Reservation;
     8	import com.pousada.domain.Room;
     9	import com.pousada.domain.RoomCatalog;
    10	import com.pousada.repository.MessageRepository;
    11	import com.pousada.repository.ReservationRepository;
    12	
    13	public class ReservationService {
    14	    private final RoomCatalog rooms;
    15	    private final ReservationRepository reservations;
    16	    private final MessageRepository messages;
    17	
    18	    public ReservationService(RoomCatalog rooms, ReservationRepository reservations, MessageRepository messages) {
    19	        this.rooms = rooms;
    20	        this.reservations = reservations;
    21	        this.messages = messages;
    22	    }
    23	
    24	    public Reservation create(NewReservation request) {
    25	        Room room = rooms.get(request.roomNumber());
    26	        if (request.guests() > room.capacity()) {
    27	            throw new DomainException(ErrorCode.CAPACITY_EXCEEDED,
    28	                    "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    29	        }
    30	        Pricing.Quote quote = Pricing.quote(room, request.checkIn(), request.checkOut(), request.ratePlan());
    31	        return reservations.create(Reservation.pending(0, room.number(), request.guestName(),
    32	                request.guestEmail(), request.guestCpf(), request.checkIn(), request.checkOut(),
    33	                request.guests(), request.ratePlan(), quote));
    34	    }
    35	
    36	    public Reservation get(long id) {
    37	        return reservations.find(id).orElseThrow(() -> new DomainException(
    38	                ErrorCode.RESERVATION_NOT_FOUND, "Reserva " + id + " não existe"));
    39	    }
    40	
    41	    public Reservation confirm(long id) {
    42	        Reservation reservation = reservations.update(id, Reservation::confirm);
    43	        messages.save(ConfirmationEmail.of(reservation.getGuestName(), reservation.getGuestEmail(),
    44	                receiptOf(reservation)));
    45	        return reservation;
    46	    }
    47	
    48	    public Reservation cancel(long id) {
    49	        return reservations.update(id, Reservation::cancel);
    50	    }
    51	
    52	    public Reservation checkIn(long id) {
    53	        return reservations.update(id, Reservation::checkIn);
    54	    }
    55	
    56	    public Receipt checkOut(long id) {
    57	        return receiptOf(reservations.update(id, Reservation::checkOut));
    58	    }
    59	
    60	    /** Segunda via: só existe para reserva paga. */
    61	    public Receipt document(long id) {
    62	        Reservation reservation = get(id);
    63	        if (!reservation.getStatus().paid()) {
    64	            throw new DomainException(ErrorCode.OPERATION_NOT_ALLOWED,
    65	                    "Reserva " + id + " está " + reservation.getStatus() + " e não tem comprovante");
    66	        }
    67	        return receiptOf(reservation);
    68	    }
    69	
    70	    private Receipt receiptOf(Reservation reservation) {
    71	        return Receipt.of(reservation, rooms.get(reservation.getRoomNumber()));
    72	    }
    73	}

