    24	    public Reservation create(NewReservation request) {
    25	        Room room = rooms.get(request.roomNumber());
    26	        if (request.guests() > room.capacity()) {
    27	            throw new DomainException(ErrorCode.CAPACITY_EXCEEDED,
    28	                    "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    29	        }
    30	        Pricing.Quote quote = Pricing.quote(room, request.checkIn(), request.checkOut(), request.ratePlan());
    31	        return reservations.create(Reservation.pending(0, room.number(), request.guestName(),
    32	                request.guestEmail(), request.guestCpf(), request.checkIn(), request.checkOut(),
    33	                request.guests(), request.ratePlan(), quote));
    34	    }
