    42	        Reservation reservation = reservations.update(id, Reservation::confirm);
    43	        messages.save(ConfirmationEmail.of(reservation.getGuestName(), reservation.getGuestEmail(),
    44	                receiptOf(reservation)));
    45	        return reservation;
    46	    }
