     8	                      RoomType roomType, LocalDate checkIn, LocalDate checkOut, int nights,
     9	                      BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    10	
    11	    private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    12	
    13	    public static Receipt of(Reservation r, Room room) {
    14	        return new Receipt("Comprovante de reserva", r.getId(), r.getGuestName(), r.getGuestCpf(),
    15	                room.number(), room.type(), r.getCheckIn(), r.getCheckOut(), r.getNights(),
    16	                r.getSubtotal(), r.getDiscount(), r.getTotal());
    17	    }
    18	
    19	    /** O texto do comprovante, igual no e-mail e na segunda via. */
    20	    public String format() {
    21	        var text = new StringBuilder();
    22	        text.append(title).append(" nº ").append(reservationId).append('\n');
    23	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(formatCpf(guestCpf)).append(")\n");
    24	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
    25	        text.append("Entrada: ").append(checkIn.format(DATE)).append(" | Saída: ").append(checkOut.format(DATE))
    26	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
    27	        text.append("Diárias: ").append(Money.brl(subtotal)).append('\n');
    28	        if (discount.signum() > 0) {
    29	            text.append("Desconto: ").append(Money.brl(discount)).append('\n');
    30	        }
    31	        text.append("Total: ").append(Money.brl(total));
    32	        return text.toString();
    33	    }
    34	
    35	    private static String formatCpf(String cpf) {
    36	        if (cpf.matches("\\d{11}")) {
    37	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." + cpf.substring(6, 9) + "-" + cpf.substring(9);
    38	        }
    39	        return cpf;
    40	    }
    41	}
