     7	import java.time.YearMonth;
     8	import java.time.format.DateTimeParseException;
     9	import java.util.Comparator;
    10	import java.util.List;
    11	
    12	/** Base dos relatórios de um mês, sobre as reservas que começam nele. */
    13	public abstract class MonthlyReport extends Report<YearMonth> {
    14	    private final ReservationRepository reservations;
    15	
    16	    protected MonthlyReport(ReservationRepository reservations) {
    17	        this.reservations = reservations;
    18	    }
    19	
    20	    @Override
    21	    public String parameter() {
    22	        return "month";
    23	    }
    24	
    25	    @Override
    26	    protected YearMonth parsePeriod(String raw) {
    27	        try {
    28	            return YearMonth.parse(raw);
    29	        } catch (DateTimeParseException | NullPointerException e) {
    30	            throw new DomainException(ErrorCode.INVALID_REQUEST, "Mês inválido, use o formato 2027-07");
    31	        }
    32	    }
    33	
    34	    @Override
    35	    protected String periodLabel(YearMonth month) {
    36	        return month.toString();
    37	    }
    38	
    39	    /** Reservas que começam no mês, por data de entrada e depois por número. */
    40	    protected List<Reservation> startingIn(YearMonth month) {
    41	        return reservations.findAll().stream()
    42	                .filter(r -> YearMonth.from(r.getCheckIn()).equals(month))
    43	                .sorted(Comparator.comparing(Reservation::getCheckIn).thenComparing(Reservation::getId))
    44	                .toList();
    45	    }
    46	
    47	    /** As que deixaram dinheiro com a pousada: o que o financeiro e o relatório de planos contam. */
    48	    protected List<Reservation> retainingMoney(YearMonth month) {
    49	        return startingIn(month).stream().filter(r -> r.retainedAmount().signum() > 0).toList();
    50	    }
    51	}
