    30	    public final String render(String rawPeriod) {
    31	        P period = parsePeriod(rawPeriod);
    32	        Body body = body(period);
    33	        var csv = new StringBuilder();
    34	        line(csv, List.of(HOUSE_NAME, name(), periodLabel(period)));
    35	        line(csv, header());
