     8	
     9	/** Conexões com o PostgreSQL, criação das tabelas e transações. */
    10	public class Database {
    11	
    12	    @FunctionalInterface
    13	    public interface Work<T> {
    14	        T run(Connection connection) throws SQLException;
    15	    }
    16	
    17	    private final DataSource dataSource;
    18	
    19	    public Database(DataSource dataSource) {
    20	        this.dataSource = dataSource;
    21	    }
    22	
    23	    public static Database connect(String url, String user, String password) {
    24	        var config = new HikariConfig();
    25	        config.setJdbcUrl(url);
    26	        config.setUsername(user);
    27	        config.setPassword(password);
    28	        config.setMaximumPoolSize(10);
    29	        config.setInitializationFailTimeout(60_000);
    30	        var database = new Database(new HikariDataSource(config));
    31	        database.createSchema();
    32	        return database;
    33	    }
    34	
    35	    public void createSchema() {
    36	        inTransaction(c -> {
    37	            try (var st = c.createStatement()) {
    38	                st.execute("SELECT pg_advisory_xact_lock(7070)");
    39	                st.execute("""
    40	                        CREATE TABLE IF NOT EXISTS reservations (
    41	                            id BIGSERIAL PRIMARY KEY,
    42	                            room_number INT NOT NULL,
    43	                            guest_name TEXT NOT NULL,
    44	                            guest_email TEXT NOT NULL,
    45	                            guest_cpf TEXT NOT NULL,
    46	                            check_in DATE NOT NULL,
    47	                            check_out DATE NOT NULL,
    48	                            guests INT NOT NULL,
    49	                            rate_plan TEXT NOT NULL,
    50	                            nights INT NOT NULL,
    51	                            subtotal NUMERIC(12,2) NOT NULL,
    52	                            discount NUMERIC(12,2) NOT NULL,
    53	                            total NUMERIC(12,2) NOT NULL,
    54	                            status TEXT NOT NULL,
    55	                            amount_paid NUMERIC(12,2) NOT NULL,
    56	                            refund NUMERIC(12,2)
    57	                        )""");
    58	                st.execute("""
    59	                        CREATE TABLE IF NOT EXISTS messages (
    60	                            id BIGSERIAL PRIMARY KEY,
    61	                            channel TEXT NOT NULL,
    62	                            recipient TEXT NOT NULL,
    63	                            subject TEXT NOT NULL,
    64	                            body TEXT NOT NULL
    65	                        )""");
    66	            }
    67	            return null;
    68	        });
    69	    }
    70	
    71	    public <T> T inTransaction(Work<T> work) {
    72	        try (Connection connection = dataSource.getConnection()) {
    73	            connection.setAutoCommit(false);
    74	            try {
    75	                T result = work.run(connection);
    76	                connection.commit();
    77	                return result;
    78	            } catch (SQLException | RuntimeException e) {
    79	                connection.rollback();
    80	                throw e;
    81	            }
    82	        } catch (SQLException e) {
    83	            throw new IllegalStateException("Erro no banco de dados", e);
    84	        }
    85	    }
    86	}
