    19	public class PostgresReservationRepository implements ReservationRepository {
    20	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, "
    21	            + "check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
    22	
    23	    private final Database database;
    24	
    25	    public PostgresReservationRepository(Database database) {
    26	        this.database = database;
    27	    }
    28	
    29	    @Override
    30	    public Reservation create(Reservation draft) {
    31	        return database.inTransaction(c -> {
    32	            try (var st = c.prepareStatement("SELECT pg_advisory_xact_lock(?)")) {
    33	                st.setInt(1, draft.getRoomNumber());
    34	                st.execute();
    35	            }
    36	            try (var st = c.prepareStatement("SELECT 1 FROM reservations WHERE room_number = ? "
    37	                    + "AND status <> 'CANCELLED' AND check_in < ? AND check_out > ? LIMIT 1")) {
    38	                st.setInt(1, draft.getRoomNumber());
    39	                st.setObject(2, draft.getCheckOut());
    40	                st.setObject(3, draft.getCheckIn());
    41	                try (ResultSet rs = st.executeQuery()) {
    42	                    if (rs.next()) {
    43	                        throw new DomainException(ErrorCode.ROOM_UNAVAILABLE,
    44	                                "Quarto " + draft.getRoomNumber() + " já reservado em alguma das noites");
    45	                    }
    46	                }
    47	            }
    48	            try (var st = c.prepareStatement("INSERT INTO reservations (room_number, guest_name, guest_email, "
    49	                    + "guest_cpf, check_in, check_out, guests, rate_plan, nights, subtotal, discount, total, "
    50	                    + "status, amount_paid, refund) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id")) {
    51	                st.setInt(1, draft.getRoomNumber());
    52	                st.setString(2, draft.getGuestName());
    53	                st.setString(3, draft.getGuestEmail());
    54	                st.setString(4, draft.getGuestCpf());
    55	                st.setObject(5, draft.getCheckIn());
    56	                st.setObject(6, draft.getCheckOut());
    57	                st.setInt(7, draft.getGuests());
    58	                st.setString(8, draft.getRatePlan().name());
    59	                st.setInt(9, draft.getNights());
    60	                st.setBigDecimal(10, draft.getSubtotal());
    61	                st.setBigDecimal(11, draft.getDiscount());
    62	                st.setBigDecimal(12, draft.getTotal());
    63	                st.setString(13, draft.getStatus().name());
    64	                st.setBigDecimal(14, draft.getAmountPaid());
    65	                st.setBigDecimal(15, draft.getRefund());
    66	                try (ResultSet rs = st.executeQuery()) {
    67	                    rs.next();
    68	                    return draft.withId(rs.getLong(1));
    69	                }
    70	            }
    71	        });
    72	    }
    73	
    74	    @Override
    75	    public Optional<Reservation> find(long id) {
    76	        return database.inTransaction(c -> select(c, id, false));
    77	    }
    78	
    79	    @Override
    80	    public Reservation update(long id, Consumer<Reservation> change) {
    81	        return database.inTransaction(c -> {
    82	            Reservation reservation = select(c, id, true).orElseThrow(() -> new DomainException(
    83	                    ErrorCode.RESERVATION_NOT_FOUND, "Reserva " + id + " não existe"));
    84	            change.accept(reservation);
    85	            try (var st = c.prepareStatement("UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
    86	                st.setString(1, reservation.getStatus().name());
    87	                st.setBigDecimal(2, reservation.getAmountPaid());
    88	                st.setBigDecimal(3, reservation.getRefund());
    89	                st.setLong(4, id);
    90	                st.executeUpdate();
    91	            }
    92	            return reservation;
    93	        });
    94	    }
    95	
    96	    @Override
    97	    public List<Reservation> findAll() {
    98	        return database.inTransaction(c -> {
    99	            var result = new ArrayList<Reservation>();
   100	            try (var st = c.prepareStatement("SELECT " + COLUMNS + " FROM reservations ORDER BY id");
   101	                 ResultSet rs = st.executeQuery()) {
   102	                while (rs.next()) {
   103	                    result.add(map(rs));
   104	                }
   105	            }
   106	            return result;
   107	        });
   108	    }
   109	
   110	    private Optional<Reservation> select(Connection c, long id, boolean lock) throws SQLException {
   111	        String sql = "SELECT " + COLUMNS + " FROM reservations WHERE id = ?" + (lock ? " FOR UPDATE" : "");
   112	        try (PreparedStatement st = c.prepareStatement(sql)) {
   113	            st.setLong(1, id);
   114	            try (ResultSet rs = st.executeQuery()) {
   115	                return rs.next() ? Optional.of(map(rs)) : Optional.empty();
   116	            }
   117	        }
   118	    }
   119	
   120	    private Reservation map(ResultSet rs) throws SQLException {
   121	        BigDecimal refund = rs.getBigDecimal("refund");
   122	        return new Reservation(rs.getLong("id"), rs.getInt("room_number"), rs.getString("guest_name"),
   123	                rs.getString("guest_email"), rs.getString("guest_cpf"),
   124	                rs.getObject("check_in", LocalDate.class), rs.getObject("check_out", LocalDate.class),
   125	                rs.getInt("guests"), RatePlan.valueOf(rs.getString("rate_plan")), rs.getInt("nights"),
   126	                rs.getBigDecimal("subtotal"), rs.getBigDecimal("discount"), rs.getBigDecimal("total"),
   127	                ReservationStatus.valueOf(rs.getString("status")), rs.getBigDecimal("amount_paid"), refund);
   128	    }
