197	import com.pousada.domain.DomainException;
198	import com.pousada.domain.ErrorCode;
199	import com.pousada.domain.Reservation;
200	import com.pousada.domain.ReservationStatus;
201	import com.pousada.repository.ReservationRepository;
202	import java.util.ArrayList;
203	import java.util.List;
204	import java.util.Optional;
205	import java.util.function.Consumer;
206	
207	class InMemoryReservationRepository implements ReservationRepository {
208	    private final List<Reservation> all = new ArrayList<>();
209	
210	    @Override
211	    public synchronized Reservation create(Reservation draft) {
212	        boolean taken = all.stream().anyMatch(r -> r.getRoomNumber() == draft.getRoomNumber()
213	                && r.getStatus() != ReservationStatus.CANCELLED
214	                && r.getCheckIn().isBefore(draft.getCheckOut()) && r.getCheckOut().isAfter(draft.getCheckIn()));
215	        if (taken) {
216	            throw new DomainException(ErrorCode.ROOM_UNAVAILABLE, "ocupado");
217	        }
218	        Reservation saved = draft.withId(all.size() + 1);
219	        all.add(saved);
220	        return saved;
221	    }
222	
223	    @Override
224	    public synchronized Optional<Reservation> find(long id) {
225	        return all.stream().filter(r -> r.getId() == id).findFirst();
226	    }
227	
228	    @Override
229	    public synchronized Reservation update(long id, Consumer<Reservation> change) {
230	        Reservation r = find(id).orElseThrow(() -> new DomainException(ErrorCode.RESERVATION_NOT_FOUND, "não existe"));
231	        change.accept(r);
232	        return r;
233	    }
234	
235	    @Override
236	    public synchronized List<Reservation> findAll() {
237	        return List.copyOf(all);
238	    }
239	}

